package com.nigson.integration.notification;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.PrivateWorkload;
import static org.assertj.core.api.Assertions.*;

class NotificationReceiptPersistenceTest {
 VerificationIntakePersistenceTest f;NotificationReceiptService service;PrivateWorkload.Proof proof;UUID id,correlation=UUID.randomUUID();String sid,account="AC"+"0".repeat(32);
 @BeforeEach void setup(){sid="SM"+UUID.randomUUID().toString().replace("-","");f=new VerificationIntakePersistenceTest();f.setup();service=new NotificationReceiptService(f.jdbc,f.manager,f.audit,Clock.systemUTC(),new SimpleMeterRegistry());var event=f.event("SMS");f.consume(event);id=f.job(event);f.jdbc.update("UPDATE integration.notification_job SET state='CLAIMED',attempt_count=1,lease_until=now()+interval '1 minute' WHERE id=?",id);f.jdbc.update("UPDATE integration.notification_dispatch SET stage='SUBMITTING',attempt_count=1,submitted_at=now(),request_hash=? WHERE id=?","a".repeat(64),id);var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-189")&&r.client().equals("nigson-commerce")).findFirst().orElseThrow();proof=new PrivateWorkload.Proof("nigson-commerce","test-commerce",route,null);}
 NotificationReceiptValues receipt(String status,String hash){return new NotificationReceiptValues(id,"TWILIO",account,sid,status,hash,null,Instant.now());}
 @Test void callbackBindsFirstProviderSidDeduplicatesAndProjectsMonotonicStates(){assertThat(service.receive(proof,receipt("queued","1".repeat(64)),correlation)).isTrue();assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,id)).isEqualTo("SENT");assertThat(f.jdbc.queryForObject("SELECT provider_message_id FROM integration.notification_dispatch WHERE id=?",String.class,id)).isEqualTo(sid);assertThat(service.receive(proof,receipt("queued","1".repeat(64)),correlation)).isTrue();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.message_receipt WHERE job_id=?",Integer.class,id)).isEqualTo(1);assertThat(service.receive(proof,receipt("delivered","2".repeat(64)),correlation)).isTrue();assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,id)).isEqualTo("DELIVERED");assertThat(service.receive(proof,receipt("sent","3".repeat(64)),correlation)).isTrue();assertThat(f.jdbc.queryForObject("SELECT state FROM integration.notification_job WHERE id=?",String.class,id)).isEqualTo("DELIVERED");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.message_receipt WHERE job_id=?",Integer.class,id)).isEqualTo(3);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,id)).isEqualTo(4);}
 @Test void accountSidMismatchAndUncheckpointedJobCannotAcquireAProviderSid(){var mismatch=new NotificationReceiptValues(id,"TWILIO","AC"+"1".repeat(32),sid,"delivered","4".repeat(64),null,Instant.now());assertThatThrownBy(()->service.receive(proof,mismatch,correlation)).isInstanceOf(Problem.Failure.class);f.jdbc.update("UPDATE integration.notification_dispatch SET stage='INTENT',request_hash=NULL,submitted_at=NULL,attempt_count=0 WHERE id=?",id);var uncheckpointed=receipt("delivered","5".repeat(64));assertThatThrownBy(()->service.receive(proof,uncheckpointed,correlation)).isInstanceOf(Problem.Failure.class);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM integration.message_receipt WHERE job_id=?",Integer.class,id)).isZero();}
 @Test void duplicateProviderMessageCannotBeBoundToAnotherJob(){service.receive(proof,receipt("queued","1".repeat(64)),correlation);UUID other=UUID.randomUUID();f.jdbc.update("INSERT INTO integration.notification_job(id,created_by,updated_by,business_key,owner_service,resource_id,template_code,template_revision,classification,state,next_attempt_at,channel,provider_mode) SELECT ?, 'test','test',?,'experience',resource_id,template_code,template_revision,classification,'CLAIMED',now(),'SMS','MOCK' FROM integration.notification_job WHERE id=?",other,"other:"+other,id);f.jdbc.update("INSERT INTO integration.notification_dispatch(id,created_by,updated_by,template_id,locale,template_snapshot,template_hash,account_sid,messaging_service_sid,account_hash,generation,source_occurred_at,correlation_id,stage,attempt_count,submitted_at,request_hash) SELECT ?, 'test','test',template_id,locale,template_snapshot,template_hash,account_sid,messaging_service_sid,account_hash,generation,source_occurred_at,correlation_id,'SUBMITTING',1,now(),? FROM integration.notification_dispatch WHERE id=?",other,"b".repeat(64),id);var mismatch=new NotificationReceiptValues(other,"TWILIO",account,sid,"delivered","6".repeat(64),null,Instant.now());assertThatThrownBy(()->service.receive(proof,mismatch,correlation)).isInstanceOf(Problem.Failure.class);}
}
